// User is the resolver for the user field.
func (r *queryResolver) User(ctx context.Context, id string) (*model.User, error) {
	// Get current user ID from context
	currentUserID, ok := middleware.GetUserID(ctx)
	if !ok || currentUserID == "" {
		return nil, fmt.Errorf("user not authenticated")
	}

	// Check if current user is admin (needed to determine error message)
	isAdmin := r.RoleService.IsAdmin(ctx, currentUserID)

	// Load requested user
	requestedUserThunk := r.Loaders.UserByIDLoader.Load(ctx, id)
	requestedUser, err := requestedUserThunk()
	if err != nil {
		// Only reveal "user not found" to admins, otherwise show permission denied
		if isAdmin {
			return nil, fmt.Errorf("failed to load requested user: %w", err)
		}
		return nil, fmt.Errorf("permission denied: you do not have access to this user")
	}

	// Check permissions
	allowed := false
	allowed = allowed || currentUserID == id                                                       // User accessing themselves
	allowed = allowed || isAdmin                                                                   // Admin or SuperAdmin
	allowed = allowed || r.RoleService.CanManageChurch(ctx, currentUserID, requestedUser.ChurchID) // Church Admin for user's church

	if !allowed {
		return nil, fmt.Errorf("permission denied: you do not have access to this user")
	}

	return requestedUser, nil
}

// Users is the resolver for the users field.
func (r *queryResolver) Users(ctx context.Context, filter *model.UserFilter, first *int, after *string, last *int, before *string) (*model.UserConnection, error) {
	// Validate user authentication and get basic info
	userInfo, err := validateUserAccess(ctx, r.Loaders.UserByIDLoader)
	if err != nil {
		return nil, err
	}

	// Check what permissions the user has
	perms, err := checkUserPermissions(ctx, r.RoleService, userInfo, filter)
	if err != nil {
		return nil, err
	}

	// Apply permission-based filters
	filter = applyPermissionFilters(filter, perms)

	// Build cache key from filter and pagination parameters
	cacheKeyParams := buildCacheKeyParams(filter, first, after, last, before)
	cacheKey := cache.UsersFilterKey(cacheKeyParams)
	countCacheKey := cache.UsersCountKey(cacheKeyParams)

	// Check cache for connection result
	if cached, ok := r.Cache.Get(cacheKey); ok {
		if connection, ok := cached.(*model.UserConnection); ok {
			return connection, nil
		}
	}

	// Decode cursors if provided
	var afterCursor, beforeCursor *string
	if after != nil && *after != "" {
		decoded, err := pagination.DecodeCursor(*after)
		if err != nil {
			return nil, fmt.Errorf("invalid after cursor: %w", err)
		}
		afterCursor = &decoded
	}
	if before != nil && *before != "" {
		decoded, err := pagination.DecodeCursor(*before)
		if err != nil {
			return nil, fmt.Errorf("invalid before cursor: %w", err)
		}
		beforeCursor = &decoded
	}

	// Build database query parameters for cursor pagination
	params, err := buildUserFilterParamsCursor(filter, first, afterCursor, last, beforeCursor)
	if err != nil {
		return nil, err
	}

	// Query database with cursor pagination
	rows, err := r.DB.Queries.GetUsersFilteredCursor(ctx, params)
	if err != nil {
		return nil, fmt.Errorf("failed to query users: %w", err)
	}

	// Query total count (check cache first)
	var totalCount int64
	countCached := false
	if cachedCount, ok := r.Cache.Get(countCacheKey); ok {
		if count, ok := cachedCount.(int64); ok {
			totalCount = count
			countCached = true
		}
	}

	// If not in cache, query database
	if !countCached {
		countParams := buildCountFilterParams(filter)
		totalCount, err = r.DB.Queries.CountUsersFiltered(ctx, countParams)
		if err != nil {
			return nil, fmt.Errorf("failed to count users: %w", err)
		}

		// Store count in cache
		r.Cache.Set(countCacheKey, totalCount)
	}

	// Determine requested limit and check if there are more results
	requestedLimit := 10 // default
	if first != nil {
		requestedLimit = *first
	} else if last != nil {
		requestedLimit = *last
	}

	hasMore := len(rows) > requestedLimit
	users := rows
	if hasMore {
		// Trim the extra record we fetched for hasMore detection
		users = rows[:requestedLimit]
	}

	// If backward pagination, reverse the results
	if last != nil {
		for i, j := 0, len(users)-1; i < j; i, j = i+1, j-1 {
			users[i], users[j] = users[j], users[i]
		}
	}

	// Convert to GraphQL model
	modelUsers := make([]model.User, len(users))
	for i, row := range users {
		// Convert birthdate to string (always valid since birthdate is required)
		birthdateStr := row.Birthdate.Time.Format("2006-01-02")

		modelUsers[i] = model.User{
			ID:        row.ID,
			MembersID: row.MembersID,
			Email:     row.Email,
			Name:      row.Name,
			Gender:    model.Gender(row.Gender),
			Birthdate: birthdateStr,
			ChurchID:  row.ChurchID,
			Image:     row.AvatarUrl,
		}
	}

	// Build the connection
	connection := pagination.BuildUserConnection(pagination.BuildUserConnectionParams{
		Users:           modelUsers,
		RequestedFirst:  first,
		RequestedLast:   last,
		RequestedAfter:  after,
		RequestedBefore: before,
		TotalCount:      int(totalCount),
		HasMore:         hasMore,
	})

	// Store connection in cache
	r.Cache.Set(cacheKey, connection)

	return connection, nil
}

