// Churches is the resolver for the churches field.
func (r *queryResolver) Churches(ctx context.Context, filter *model.ChurchFilter, first *int, after *string, last *int, before *string) (*model.ChurchConnection, error) {
	// Build cache key from filter and pagination parameters
	cacheKeyParams := buildChurchCacheKeyParams(filter, first, after, last, before)
	cacheKey := cache.ChurchesFilterKey(cacheKeyParams)
	countCacheKey := cache.ChurchesCountKey(cacheKeyParams)

	// Check cache for connection result
	if cached, ok := r.Cache.Get(cacheKey); ok {
		if connection, ok := cached.(*model.ChurchConnection); ok {
			return connection, nil
		}
	}

	// Decode cursors if provided
	var afterCursor, beforeCursor *string
	if after != nil && *after != "" {
		decoded, err := pagination.DecodeCursor(*after)
		if err != nil {
			return nil, fmt.Errorf("invalid after cursor: %w", err)
		}
		afterCursor = &decoded
	}
	if before != nil && *before != "" {
		decoded, err := pagination.DecodeCursor(*before)
		if err != nil {
			return nil, fmt.Errorf("invalid before cursor: %w", err)
		}
		beforeCursor = &decoded
	}

	// Build database query parameters for cursor pagination
	params, err := buildChurchFilterParamsCursor(filter, first, afterCursor, last, beforeCursor)
	if err != nil {
		return nil, err
	}

	// Query database with cursor pagination
	rows, err := r.DB.Queries.GetChurchesFilteredCursor(ctx, params)
	if err != nil {
		return nil, fmt.Errorf("failed to query churches: %w", err)
	}

	// Query total count (check cache first)
	var totalCount int64
	countCached := false
	if cachedCount, ok := r.Cache.Get(countCacheKey); ok {
		if count, ok := cachedCount.(int64); ok {
			totalCount = count
			countCached = true
		}
	}

	// If not in cache, query database
	if !countCached {
		countParams := buildCountChurchesFilterParams(filter)
		totalCount, err = r.DB.Queries.CountChurchesFiltered(ctx, countParams)
		if err != nil {
			return nil, fmt.Errorf("failed to count churches: %w", err)
		}

		// Store count in cache
		r.Cache.Set(countCacheKey, totalCount)
	}

	// Determine requested limit and check if there are more results
	requestedLimit := 10 // default
	if first != nil {
		requestedLimit = *first
	} else if last != nil {
		requestedLimit = *last
	}

	hasMore := len(rows) > requestedLimit
	churches := rows
	if hasMore {
		// Trim the extra record we fetched for hasMore detection
		churches = rows[:requestedLimit]
	}

	// If backward pagination, reverse the results
	if last != nil {
		for i, j := 0, len(churches)-1; i < j; i, j = i+1, j-1 {
			churches[i], churches[j] = churches[j], churches[i]
		}
	}

	// Convert to GraphQL model
	modelChurches := make([]model.Church, len(churches))
	for i, row := range churches {
		modelChurches[i] = model.Church{
			ID:       row.ID,
			Name:     row.Name,
			Country:  row.Country,
			Category: model.ChurchCategory(row.Category),
		}
	}

	// Build the connection
	connection := pagination.BuildChurchConnection(pagination.BuildChurchConnectionParams{
		Churches:        modelChurches,
		RequestedFirst:  first,
		RequestedLast:   last,
		RequestedAfter:  after,
		RequestedBefore: before,
		TotalCount:      int(totalCount),
		HasMore:         hasMore,
	})

	// Store connection in cache
	r.Cache.Set(cacheKey, connection)

	return connection, nil
}

